        competitors: [{ name: 'Other offshore rig contractors', note: 'Indian and foreign rig owners bidding in the same ONGC tenders; all have struggled to redeploy rigs recently.' }, { name: 'International jack-up owners', note: 'Earn higher rates abroad and bid in India when their rigs are idle.' }],
